//! Sound handles (masters generated by `tools/solid_eleven/make_sounds.py`).

use trino_core::{Audio, MusicId, SoundId};

/// The crowd's murmur, looped under every match.
pub const CROWD: MusicId = MusicId::from_path("music/se_crowd");
/// The menus' theme.
pub const THEME: MusicId = MusicId::from_path("music/se_theme");

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Sfx {
    Whistle,
    Kick,
    Tap,
    Cheer,
    Ooh,
    Post,
    Click,
    Back,
}

impl Sfx {
    pub fn id(self) -> SoundId {
        match self {
            Sfx::Whistle => SoundId::from_path("sounds/se_whistle"),
            Sfx::Kick => SoundId::from_path("sounds/se_kick"),
            Sfx::Tap => SoundId::from_path("sounds/se_tap"),
            Sfx::Cheer => SoundId::from_path("sounds/se_cheer"),
            Sfx::Ooh => SoundId::from_path("sounds/se_ooh"),
            Sfx::Post => SoundId::from_path("sounds/se_post"),
            Sfx::Click => SoundId::from_path("sounds/se_click"),
            Sfx::Back => SoundId::from_path("sounds/se_back"),
        }
    }
}

pub fn play(audio: &mut dyn Audio, s: Sfx) {
    audio.play_sound(s.id());
}
